--- a/src/agent-ui/plugins/sales-report-message/schema.ts
+++ b/src/agent-ui/plugins/sales-report-message/schema.ts
@@ -1,1 +1,96 @@
-
+export const SALES_REPORT_EVENT = "app.sales.report";
+
+export interface SalesReportRow {
+  id: string;
+  month: string;
+  revenue: number | null;
+  orderCount: number | null;
+}
+
+export interface SalesReport {
+  title: string | null;
+  rows: SalesReportRow[];
+}
+
+export type SalesReportParseResult =
+  | { ok: true; report: SalesReport }
+  | { ok: false; reason: "invalid" };
+
+function parseJsonText(text: string): unknown {
+  const trimmed = text.trim();
+  if (!trimmed) return null;
+  try {
+    return JSON.parse(trimmed) as unknown;
+  } catch {
+    return null;
+  }
+}
+
+/**
+ * The report travels as a CUSTOM event value such as
+ * { format: "json", payload: "{\"title\":...,\"rows\":[...]}" }.
+ * Unwrap the JSON envelope strings until an object is reached.
+ */
+function unwrapEnvelope(value: unknown, depth: number): unknown {
+  if (depth > 5) return value;
+  if (typeof value === "string") return unwrapEnvelope(parseJsonText(value), depth + 1);
+  if (!value || typeof value !== "object") return value;
+  const record = value as Record<string, unknown>;
+  if (Array.isArray(record.rows)) return record;
+  if ("payload" in record) return unwrapEnvelope(record.payload, depth + 1);
+  if ("value" in record) return unwrapEnvelope(record.value, depth + 1);
+  return record;
+}
+
+function toNumber(input: unknown): number | null {
+  if (typeof input === "number") return Number.isFinite(input) ? input : null;
+  if (typeof input === "string") {
+    const normalized = input.replace(/[,\s]/g, "");
+    if (!normalized) return null;
+    const parsed = Number(normalized);
+    return Number.isFinite(parsed) ? parsed : null;
+  }
+  return null;
+}
+
+function normalizeRow(input: unknown, index: number): SalesReportRow | null {
+  if (!input || typeof input !== "object") return null;
+  const record = input as Record<string, unknown>;
+
+  const monthValue = record.month;
+  const month =
+    typeof monthValue === "string"
+      ? monthValue.trim()
+      : typeof monthValue === "number"
+        ? String(monthValue)
+        : "";
+  if (!month) return null;
+
+  return {
+    id: `${month}-${index}`,
+    month,
+    revenue: toNumber(record.revenue),
+    orderCount: toNumber(record.order_count ?? record.orderCount),
+  };
+}
+
+export function parseSalesReport(data: unknown): SalesReportParseResult {
+  const root = unwrapEnvelope(data, 0);
+  if (!root || typeof root !== "object" || Array.isArray(root)) {
+    return { ok: false, reason: "invalid" };
+  }
+
+  const record = root as Record<string, unknown>;
+  if (!Array.isArray(record.rows)) return { ok: false, reason: "invalid" };
+
+  const rows = record.rows
+    .map((row, index) => normalizeRow(row, index))
+    .filter((row): row is SalesReportRow => row !== null);
+  if (rows.length === 0) return { ok: false, reason: "invalid" };
+
+  const titleValue = record.title;
+  const title = typeof titleValue === "string" && titleValue.trim() ? titleValue.trim() : null;
+
+  return { ok: true, report: { title, rows } };
+}
+

--- a/src/agent-ui/plugins/sales-report-message/index.tsx
+++ b/src/agent-ui/plugins/sales-report-message/index.tsx
@@ -1,1 +1,139 @@
-
+import { Fragment, useMemo, useState } from "react";
+import { useAgentUILocaleCode } from "@za38.03/agent-ui-plugins";
+import { getProjectMessages } from "../../application/i18n/messages";
+import { parseSalesReport, type SalesReportRow } from "./schema";
+import "./styles.css";
+
+type SortDirection = "desc" | "asc";
+
+function sortRows(rows: SalesReportRow[], direction: SortDirection): SalesReportRow[] {
+  const factor = direction === "desc" ? -1 : 1;
+  return [...rows].sort((a, b) => {
+    if (a.revenue === null && b.revenue === null) return a.month.localeCompare(b.month);
+    if (a.revenue === null) return 1;
+    if (b.revenue === null) return -1;
+    if (a.revenue === b.revenue) return a.month.localeCompare(b.month);
+    return (a.revenue - b.revenue) * factor;
+  });
+}
+
+export function SalesReportMessage({ data }: { data: unknown }) {
+  const localeCode = useAgentUILocaleCode();
+  const labels = getProjectMessages(localeCode).salesReport;
+  const [direction, setDirection] = useState<SortDirection>("desc");
+  const [selectedId, setSelectedId] = useState<string | null>(null);
+  const numbers = useMemo(
+    () => new Intl.NumberFormat(localeCode, { maximumFractionDigits: 2 }),
+    [localeCode],
+  );
+  const result = useMemo(() => parseSalesReport(data), [data]);
+
+  if (!result.ok) {
+    return (
+      <section className="sales-report" role="alert">
+        <p className="sales-report__status">{labels.invalid}</p>
+      </section>
+    );
+  }
+
+  const { report } = result;
+  const heading = report.title ?? labels.heading;
+  const rows = sortRows(report.rows, direction);
+
+  const toggleRow = (rowId: string) => {
+    setSelectedId((current) => (current === rowId ? null : rowId));
+  };
+
+  const formatValue = (value: number | null) =>
+    value === null ? labels.unknown : numbers.format(value);
+
+  return (
+    <section className="sales-report" aria-label={heading}>
+      <header className="sales-report__header">
+        <h3 className="sales-report__title">{heading}</h3>
+        <p className="sales-report__hint">{labels.hint}</p>
+      </header>
+
+      {rows.length === 0 ? (
+        <p className="sales-report__status">{labels.empty}</p>
+      ) : (
+        <div className="sales-report__scroll">
+          <table className="sales-report__table" aria-label={heading}>
+            <thead>
+              <tr>
+                <th scope="col" className="sales-report__col-month">
+                  {labels.month}
+                </th>
+                <th
+                  scope="col"
+                  className="sales-report__col-revenue"
+                  aria-sort={direction === "desc" ? "descending" : "ascending"}
+                >
+                  <button
+                    type="button"
+                    className="sales-report__sort"
+                    onClick={() =>
+                      setDirection((current) => (current === "desc" ? "asc" : "desc"))
+                    }
+                  >
+                    <span>{labels.revenue}</span>
+                    <span className="sales-report__sort-icon" aria-hidden="true">
+                      {direction === "desc" ? "↓" : "↑"}
+                    </span>
+                  </button>
+                </th>
+              </tr>
+            </thead>
+            <tbody>
+              {rows.map((row) => {
+                const selected = row.id === selectedId;
+                return (
+                  <Fragment key={row.id}>
+                    <tr
+                      className="sales-report__row"
+                      data-selected={selected ? "true" : undefined}
+                      tabIndex={0}
+                      aria-expanded={selected}
+                      onClick={() => toggleRow(row.id)}
+                      onKeyDown={(event) => {
+                        if (event.key === "Enter" || event.key === " ") {
+                          event.preventDefault();
+                          toggleRow(row.id);
+                        }
+                      }}
+                    >
+                      <th scope="row" className="sales-report__col-month">
+                        {row.month}
+                      </th>
+                      <td className="sales-report__col-revenue">
+                        {formatValue(row.revenue)}
+                      </td>
+                    </tr>
+                    {selected ? (
+                      <tr className="sales-report__detail">
+                        <td colSpan={2}>
+                          <span className="sales-report__detail-inner" role="status">
+                            <span className="sales-report__detail-month">{row.month}</span>
+                            <span className="sales-report__detail-label">
+                              {labels.orderCount}
+                            </span>
+                            <span className="sales-report__detail-value">
+                              {formatValue(row.orderCount)}
+                            </span>
+                          </span>
+                        </td>
+                      </tr>
+                    ) : null}
+                  </Fragment>
+                );
+              })}
+            </tbody>
+          </table>
+        </div>
+      )}
+    </section>
+  );
+}
+
+export default SalesReportMessage;
+

