+  optionalInject: ["agent-ui.locale"],
+  dataMessageUIs: [
+    defineDataMessageUI<unknown>({
+      name: "app.sales.report",
+      render: SalesReportMessage,
+    }),
+  ],
+  Component: () => null,
+};
+
+export default definition;
